import{_ as a,C as i,o as e,c as o,j as l,a as d,E as n,a2 as s}from"./chunks/framework.aJDz64y9.js";const b=JSON.parse('{"title":"Угон → СТО → порт","description":"","frontmatter":{},"headers":[],"relativePath":"crime/car-theft.md","filePath":"crime/car-theft.md","lastUpdated":1794540927000}'),h={name:"crime/car-theft.md"};function c(g,t,p,m,_,u){const r=i("DiagramCarChain");return e(),o("div",null,[t[0]||(t[0]=l("h1",{id:"угон-→-сто-→-порт",tabindex:"-1"},[d("Угон → СТО → порт "),l("a",{class:"header-anchor",href:"#угон-→-сто-→-порт","aria-label":'Permalink to "Угон → СТО → порт"'},"​")],-1)),t[1]||(t[1]=l("p",null,"Угнанная машина почти ничего не стоит, пока её не «почистит» механик-игрок: снимет жучки, перебьёт VIN и номера. На этой зависимости держится вся цепочка.",-1)),n(r),t[2]||(t[2]=s('<p>Сплошная линия — основной путь машины: заказ, угон, перегон, чистка, рейс. Пунктир показывает, где вмешивается полиция.</p><h2 id="этапы" tabindex="-1">Этапы <a class="header-anchor" href="#этапы" aria-label="Permalink to &quot;Этапы&quot;">​</a></h2><ol><li><strong>Заказ.</strong> Экспортёр в порту раз в сутки публикует список моделей с надбавкой. Игроки тоже могут заказать машину, например под разбор. Машину вне списка берут, но дешевле.</li><li><strong>Подготовка.</strong> Инструмент зависит от класса машины — см. таблицу ниже. Запасной путь — эвакуатор: машину грузят без вскрытия, но нужен игрок с эвакуатором, и это медленно и заметно.</li><li><strong>Вскрытие и запуск.</strong> Мини-игра на замок, затем на запуск. Ошибка включает сирену. Владелец-NPC заявляет об угоне через 1–5 минут; владелец-игрок заявляет сам через телефон.</li><li><strong>Перегон.</strong> После заявления номер попадает в розыск. <ul><li>Жучок шлёт полиции положение машины раз в 20–30 секунд. Глушилка закрывает сигнал на несколько минут, пока жива батарея.</li><li>Патрульная машина со считывателем номеров получает срабатывание, если угнанная проехала рядом.</li><li>Повреждения снижают цену, поэтому уходить от погони напролом невыгодно.</li></ul></li><li><strong>СТО.</strong> Угонщик не может обработать машину сам: нужны подъёмник, инструмент и навык механика. Цену стороны назначают сами. <ul><li>Поиск жучков. Механик обходит машину со сканером и по сигналу «тепло — холодно» проверяет арки, бамперы, салон, разъём диагностики. У дорогих машин второй жучок просыпается, если сняли только первый.</li><li>Перебивка VIN. Мини-игра в двух-трёх местах кузова. Результат — «качество перебивки» от 0 до 100, которое хранится на машине и решает, пройдёт ли она полицейскую проверку.</li><li>Номера и перекраска. Поддельные пластины делает мастер; новый цвет сбивает ориентировку.</li><li>Разбор вместо продажи. Механик по одной снимает детали на подъёмнике: колёса, двери, двигатель, коробку. Детали становятся предметами и идут в легальный ремонт дешевле заводских. Это та же «скрутка», только руками механика и с пользой для экономики.</li><li>Риск механика. Полиция может приехать с проверкой: машина в розыске на подъёмнике, срезанные таблички и журнал работ — вещдоки.</li><li>NPC-замена. Гаражный мастер в глуши работает дорого, долго и с низким качеством перебивки.</li></ul></li><li><strong>Порт.</strong> Экспортёр принимает машины рейсами: 2–3 окна в сутки по 20–30 минут, точек погрузки несколько. <ul><li>Цена = база × надбавка заказа × состояние кузова × чистота (сняты ли жучки, качество перебивки).</li><li>Машина с работающим жучком приводит полицию к причалу, и приёмка закрывается для всех на час. Виновного будут искать свои же.</li><li>Окна рейсов известны и полиции, и конкурентам: возможны засады и перехват по дороге.</li></ul></li></ol><table tabindex="0"><thead><tr><th>Класс машины</th><th>Замок</th><th>Запуск</th><th>Защита</th><th>Команда</th></tr></thead><tbody><tr><td>Старые и дешёвые</td><td>Отмычка</td><td>Проводка под рулём</td><td>Нет</td><td>1</td></tr><tr><td>Средние</td><td>Отмычка, замок сложнее</td><td>Программатор ключа</td><td>Сирена, один жучок</td><td>2</td></tr><tr><td>Дорогие</td><td>Ретранслятор ключа: один человек у двери владельца, второй у машины</td><td>Тот же ретранслятор</td><td>Сирена, два жучка, один спрятан</td><td>2–3</td></tr></tbody></table><p>Люди в цепочке: заказчик, напарник с ретранслятором, водитель эвакуатора, механик, мастер номеров, полиция, конкурирующая команда.</p><h2 id="машины-игроков" tabindex="-1">Машины игроков <a class="header-anchor" href="#машины-игроков" aria-label="Permalink to &quot;Машины игроков&quot;">​</a></h2><p>На старте угоняются только машины NPC; машины игроков подключаются позже и с четырьмя ограничениями.</p><ul><li><strong>Угнанную машину игрока нельзя оставить себе.</strong> Она уходит только в порт или на разбор, иначе машины можно будет размножать.</li><li><strong>Возврат владельцу.</strong> Страховки на сервере нет, поэтому её вводят вместе с этим этапом: взнос раз в неделю, возврат машины через сутки, франшиза. Без страховки машина возвращается через штрафстоянку за полную плату.</li><li><strong>Защита от фарма.</strong> Выплата вору в порту всегда ниже того, что владелец платит за возврат. Иначе двое друзей будут гонять одну машину по кругу и печатать деньги.</li><li><strong>Жучок — покупка владельца.</strong> Владелец с жучком видит последний сигнал в телефоне и может поехать за машиной сам или с полицией.</li></ul>',8))])}const C=a(h,[["render",c]]);export{b as __pageData,C as default};
